
import { defineComponent, PropType } from 'vue';
import { translate } from 'CoreHome';
import Markdown from '../Markdown.vue';
import ChatAgentSteps from './ChatAgentSteps.vue';
import IconAi from '../Icon/IconAi.vue';
import ChatIcon from '../Icon/ChatIcon.vue';
import { Message } from '../../types';
import writeToClipboard from '../clipboard';

const COPIED_FEEDBACK_MS = 2000;

export default defineComponent({
  components: {
    ChatAgentSteps,
    ChatIcon,
    IconAi,
    Markdown,
  },
  props: {
    message: {
      type: Object as PropType<Message>,
      required: true,
    },
    index: {
      type: Number,
      required: true,
    },
    aiName: {
      type: String,
      required: true,
    },
    aiLabel: {
      type: String,
      default: '',
    },
    isStreaming: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      copied: false,
      copiedTimer: 0,
    };
  },
  computed: {
    isUser(): boolean {
      return this.message.role === 'user';
    },
    copyText(): string {
      return translate('ChatGPT_CopyAnswer');
    },
    copiedText(): string {
      return translate('ChatGPT_AnswerCopied');
    },
  },
  beforeUnmount() {
    window.clearTimeout(this.copiedTimer);
  },
  methods: {
    translate,
    async copyAnswer() {
      try {
        await writeToClipboard(this.message.content);
      } catch {
        return;
      }
      this.copied = true;
      window.clearTimeout(this.copiedTimer);
      this.copiedTimer = window.setTimeout(() => {
        this.copied = false;
      }, COPIED_FEEDBACK_MS);
    },
  },
});
