
import { defineComponent, PropType } from 'vue';

export type ChatIconName = 'send' | 'arrow-down' | 'copy' | 'check' | 'close' | 'error'
  | 'chevron' | 'plus' | 'tool';

export default defineComponent({
  props: {
    name: {
      type: String as PropType<ChatIconName>,
      required: true,
    },
    size: {
      type: Number,
      default: 16,
    },
  },
});
